#!/usr/bin/env python3
"""Generate large, realistic Markdown files for performance testing mmd.

    python3 testdata/perf/generate.py          # writes large.md (~200KB) and huge.md (~2MB) next to this script

Output is deterministic (fixed seed), so benchmark runs are comparable across builds. Each document
mixes everything the styler handles: headings, paragraphs with inline formatting and links, bullet,
numbered and task lists, quotes, tables, code fences and rules.
"""
import os
import random

WORDS = ("the of and to in is for on with as by at from that this it be are was an or which their "
         "system frame layout render text style budget latency window preview editor table column "
         "scroll resize glass color theme scheme font spacing paragraph heading quote list code fence "
         "link file trace span percentile metric benchmark cache memory disk kernel thread queue").split()


PAGES = ["../01-text.md", "../02-tables.md", "../04-code.md", "../05-links.md", "README.md"]


def sentence(r, n=None):
    n = n or r.randint(8, 22)
    words = [r.choice(WORDS) for _ in range(n)]
    out = []
    for w in words:
        roll = r.random()
        if roll < 0.04:
            w = f"**{w}**"
        elif roll < 0.07:
            w = f"*{w}*"
        elif roll < 0.09:
            w = f"`{w}`"
        elif roll < 0.10:
            w = f"[{w}]({r.choice(PAGES)})"
        out.append(w)
    s = " ".join(out)
    return s[0].upper() + s[1:] + "."


def paragraph(r):
    return " ".join(sentence(r) for _ in range(r.randint(2, 6)))


def table(r):
    cols = r.randint(2, 5)
    head = "| " + " | ".join(r.choice(WORDS).title() for _ in range(cols)) + " |"
    sep = "|" + "|".join(r.choice(["---", ":--", ":-:", "--:"]) for _ in range(cols)) + "|"
    rows = ["| " + " | ".join(sentence(r, r.randint(1, 9)).rstrip(".") for _ in range(cols)) + " |"
            for _ in range(r.randint(3, 8))]
    return "\n".join([head, sep] + rows)


def code(r):
    lines = [f"    let {r.choice(WORDS)}{i} = {r.randint(0, 999)}  // {sentence(r, 4)}" for i in range(r.randint(3, 12))]
    return "```swift\nfunc example() {\n" + "\n".join(lines) + "\n}\n```"


def section(r, i):
    parts = [f"## {i}. {sentence(r, 4).rstrip('.')}", paragraph(r)]
    for _ in range(r.randint(2, 5)):
        kind = r.random()
        if kind < 0.35:
            parts.append(paragraph(r))
        elif kind < 0.5:
            parts.append("\n".join(f"- {sentence(r, r.randint(4, 12))}" for _ in range(r.randint(2, 6))))
        elif kind < 0.6:
            parts.append("\n".join(f"{n + 1}. {sentence(r, r.randint(4, 12))}" for n in range(r.randint(2, 6))))
        elif kind < 0.67:
            parts.append("\n".join(f"- [{r.choice([' ', 'x'])}] {sentence(r, r.randint(3, 8))}" for _ in range(r.randint(2, 5))))
        elif kind < 0.75:
            parts.append("> " + paragraph(r))
        elif kind < 0.87:
            parts.append(table(r))
        elif kind < 0.97:
            parts.append(code(r))
        else:
            parts.append("---")
    return "\n\n".join(parts)


def generate(path, target_bytes, seed, title):
    r = random.Random(seed)
    chunks = [f"# {title}\n\n[← Back to the perf index](README.md)\n\nGenerated by `generate.py` (seed {seed}). "
              "Scroll it, jump around with the scroller, resize the window, and type in the middle in the editor.\n"]
    size, i = len(chunks[0]), 1
    while size < target_bytes:
        s = section(r, i) + "\n"
        chunks.append(s)
        size += len(s.encode())
        i += 1
    with open(path, "w") as f:
        f.write("\n".join(chunks))
    print(f"{path}: {size:,} bytes, {i - 1} sections")


if __name__ == "__main__":
    here = os.path.dirname(os.path.abspath(__file__))
    generate(os.path.join(here, "large.md"), 200_000, 1, "Large document (~200KB)")
    generate(os.path.join(here, "huge.md"), 2_000_000, 2, "Huge document (~2MB)")
